#!/usr/bin/env python3
"""Upload TV-Face hub fixes. Source FLEET_ADMIN_SECRET first or pass as env."""
import base64, json, os, pathlib, subprocess, sys, tempfile

PAYLOAD = r'{"AVATARS.html": "", "code/tv-face/tv-face.js": "", "code/tv-face/demo.html": "", "docs/SVG-BLOUB-NOTES.md": ""}'

def main():
    secret = os.environ.get('FLEET_ADMIN_SECRET') or os.environ.get('FLEET_AUTH_SECRET')
    if not secret:
        for p in [
            pathlib.Path.home()/'.secrets/fleet-share-auth.env',
            pathlib.Path('/home/box/.secrets/fleet-share-auth.env'),
            pathlib.Path.home()/'.secrets/fleetlink-auth.env',
        ]:
            if p.is_file():
                for line in p.read_text().splitlines():
                    line=line.strip()
                    if not line or line.startswith('#') or '=' not in line: continue
                    k,v=line.split('=',1)
                    os.environ.setdefault(k.strip(), v.strip().strip('"').strip("'"))
                secret = os.environ.get('FLEET_ADMIN_SECRET') or os.environ.get('FLEET_AUTH_SECRET')
                break
    if not secret:
        sys.exit('missing FLEET_ADMIN_SECRET')
    files = json.loads(PAYLOAD)
    ctypes = {
        'AVATARS.html': 'text/html; charset=utf-8',
        'code/tv-face/tv-face.js': 'application/javascript; charset=utf-8',
        'code/tv-face/demo.html': 'text/html; charset=utf-8',
        'docs/SVG-BLOUB-NOTES.md': 'text/markdown; charset=utf-8',
    }
    base = 'https://fleetlink.online/TV-Face'
    with tempfile.TemporaryDirectory() as td:
        td = pathlib.Path(td)
        for rel, b64 in files.items():
            path = td/rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(base64.b64decode(b64))
            url = f'{base}/{rel}'
            r = subprocess.run([
                'curl','-sS','-o','/tmp/fl-up-body.txt','-w','%{http_code}',
                '-X','PUT', url, '-T', str(path),
                '-H', f'X-Fleet-Auth: {secret}',
                '-H', f'Content-Type: {ctypes[rel]}',
                '-H', 'X-Expire-Days: forever',
            ], capture_output=True, text=True)
            body = pathlib.Path('/tmp/fl-up-body.txt').read_text()[:160] if pathlib.Path('/tmp/fl-up-body.txt').exists() else ''
            print(f'{rel} -> {r.stdout} {body}')
    print('DONE')

if __name__ == '__main__':
    main()
